import csv

def summarise(path):
    count = total = 0
    with open(path, newline='') as source:
        for row in csv.DictReader(source):
            try:
                score = int(row['score'])
                if not row['name'].strip() or not 0 <= score <= 100:
                    continue
                count += 1
                total += score
            except (ValueError, TypeError, KeyError):
                continue
    return [count, total]
